int main() {
    char s[2000];
    int arr[200];
    int n = 0;

    fgets(s, sizeof(s), stdin);

    char *p = s;

    while (*p) {
        if (isdigit(*p) || *p == '-') {
            char *end;
            arr[n++] = (int)strtol(p, &end, 10);
            p = end;
        } else {
            p++;
        }
    }

    int k = arr[n - 1];
    int target = arr[k];
    int time = 0;

    for (int i = 0; i < n - 1; i++) {
        if (i <= k) {
            time += (arr[i] < target) ? arr[i] : target;
        } else {
            time += (arr[i] < target - 1) ? arr[i] : target - 1;
        }
    }

    printf("%d", time);

    return 0;
}

