import java.util.*;
import java.util.regex.*;

public class Solution {
    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);
        StringBuilder input = new StringBuilder();

        while (sc.hasNextLine()) {
            input.append(sc.nextLine()).append(" ");
        }

        String s = input.toString();

        Matcher gm = Pattern.compile("\"([.X]+)\"").matcher(s);
        ArrayList<String> rows = new ArrayList<>();

        while (gm.find()) {
            rows.add(gm.group(1));
        }

        int n = rows.size();
        String[] grid = rows.toArray(new String[0]);

        Matcher nm = Pattern.compile("-?\\d+").matcher(s);
        ArrayList<Integer> nums = new ArrayList<>();

        while (nm.find()) {
            nums.add(Integer.parseInt(nm.group()));
        }

        int sx = nums.get(nums.size() - 4);
        int sy = nums.get(nums.size() - 3);
        int gx = nums.get(nums.size() - 2);
        int gy = nums.get(nums.size() - 1);

        boolean[][] vis = new boolean[n][n];
        Queue<int[]> q = new LinkedList<>();

        q.add(new int[]{sx, sy, 0});
        vis[sx][sy] = true;

        int[] dx = {1, -1, 0, 0};
        int[] dy = {0, 0, 1, -1};

        while (!q.isEmpty()) {
            int[] cur = q.poll();

            int x = cur[0];
            int y = cur[1];
            int d = cur[2];

            if (x == gx && y == gy) {
                System.out.print(d);
                return;
            }

            for (int k = 0; k < 4; k++) {
                int nx = x;
                int ny = y;

                while (nx + dx[k] >= 0 &&
                       nx + dx[k] < n &&
                       ny + dy[k] >= 0 &&
                       ny + dy[k] < n &&
                       grid[nx + dx[k]].charAt(ny + dy[k]) != 'X') {

                    nx += dx[k];
                    ny += dy[k];

                    if (!vis[nx][ny]) {
                        vis[nx][ny] = true;
                        q.add(new int[]{nx, ny, d + 1});
                    }
                }
            }
        }
    }
}

