    int n = grid.size();

    vector<int> nums;

    for (int i = 0; i < (int)s.size(); ) {
        if (isdigit(s[i]) || s[i] == '-') {
            int sign = 1;

            if (s[i] == '-') {
                sign = -1;
                i++;
            }

            int num = 0;

            while (i < (int)s.size() && isdigit(s[i])) {
                num = num * 10 + (s[i] - '0');
                i++;
