                   ny + dy[k] >= 0 &&
                   ny + dy[k] < n &&
                   grid[nx + dx[k]][ny + dy[k]] != 'X') {

                nx += dx[k];
                ny += dy[k];

                if (dist[nx][ny] == -1) {
                    dist[nx][ny] = dist[x][y] + 1;
