import java.util.*;

class Solution {

    static Stack<Integer> s1 = new Stack<>();
    static Stack<Integer> s2 = new Stack<>();

    static void move(){
        if(s2.isEmpty()){
            while(!s1.isEmpty()){
                s2.push(s1.pop());
            }
        }
    }

    static void push(int x){
        s1.push(x);
    }

    static int pop(){
        move();
        return s2.pop();
    }

    static int peek(){
        move();
        return s2.peek();
    }

    static boolean empty(){
        return s1.isEmpty() && s2.isEmpty();
    }

    public static void main(String[] args){
        Scanner sc = new Scanner(System.in);
        String line = sc.nextLine();

        String[] ops = line.split(",");
        List<String> res = new ArrayList<>();

        for(String op : ops){
            op = op.trim();

            if(op.startsWith("push")){
                int val = Integer.parseInt(op.substring(5, op.length()-1));
                push(val);
            }
            else if(op.startsWith("pop")){
                res.add(String.valueOf(pop()));
            }
            else if(op.startsWith("peek")){
                res.add(String.valueOf(peek()));
            }
            else if(op.startsWith("empty")){
                res.add(String.valueOf(empty()));
            }
        }

        System.out.println(String.join(",", res));
    }
}

