int s1[10000], s2[10000];
int top1 = -1, top2 = -1;

void move() {
    if (top2 == -1) {
        while (top1 != -1) {
            s2[++top2] = s1[top1--];
        }
    }
}

void push(int x) {
    s1[++top1] = x;
}

int pop_op() {
    move();
    if (top2 != -1) {
        return s2[top2--];
    }
    return -1;
}

int peek() {
    move();
    if (top2 != -1) {
        return s2[top2];
    }
    return -1;
}

int empty() {
    return (top1 == -1 && top2 == -1);
}

