        size = k;
        q = new int[k];
    }

    public boolean enQueue(int value) {
        if (count == size) return false;
        q[(head + count) % size] = value;
        count++;
        return true;
    }

    public boolean deQueue() {
        if (count == 0) return false;
        head = (head + 1) % size;
        count--;
        return true;
    }

    public int Front() {
        return count == 0 ? -1 : q[head];
    }

