        int m=Integer.parseInt(m1.group(1));
        int k=Integer.parseInt(m2.group(1));

        MKAverage mk=new MKAverage(m,k);

        Matcher ops=Pattern.compile("addElement\\((.*?)\\)").matcher(line);

        while(ops.find()){

            String v=ops.group(1);

            if(v.contains("..")){
                String[] p=v.split("\\.\\.");
                int a=Integer.parseInt(p[0]);
                int b=Integer.parseInt(p[1]);

                for(int i=a;i<=b;i++)
                    mk.addElement(i);
            }
            else{
