#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <ctype.h>

int q[10000];
int size = 0, m, k;

void addElement(int num) {
    if (size < m) {
        q[size++] = num;
    } else {
        for (int i = 1; i < m; i++) {
            q[i - 1] = q[i];
        }
        q[m - 1] = num;
    }
}

int cmp(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;

    return (x > y) - (x < y);
}

int calculateMKAverage() {
    if (size < m) return -1;

    int arr[10000];

    for (int i = 0; i < m; i++) {
        arr[i] = q[i];
    }

    qsort(arr, m, sizeof(int), cmp);

    long long sum = 0;

    for (int i = k; i < m - k; i++) {
        sum += arr[i];
    }

    return (int)(sum / (m - 2 * k));
}

