        k = atoi(p + 2);
    }

    p = strstr(input, "addElement(");

    while (p != NULL) {
        p += strlen("addElement(");

        char *endBracket = strchr(p, ')');

        if (endBracket == NULL) break;

        char content[5000];
        int len = endBracket - p;

        strncpy(content, p, len);
        content[len] = '\0';

        char *range = strstr(content, "..");

        if (range != NULL) {
            *range = '\0';

            int start = atoi(content);
            int end = atoi(range + 2);

            if (start <= end) {
                for (int i = start; i <= end; i++) {
                    addElement(i);
                }
            } else {
                for (int i = start; i >= end; i--) {
                    addElement(i);
                }
            }
        } else {
            char *cur = content;

            while (*cur) {
                while (*cur && !isdigit(*cur) && *cur != '-') {
                    cur++;
                }

                if (!*cur) break;

                char *end;
                int num = (int)strtol(cur, &end, 10);

                addElement(num);
                cur = end;
            }
        }

        p = strstr(endBracket + 1, "addElement(");
    }

    printf("%d", calculateMKAverage());

    return 0;
}

