class MKAverage{
public:
    int m,k;
    queue<int> q;

    MKAverage(int m,int k){
        this->m=m;
        this->k=k;
    }

    void addElement(int num){
        q.push(num);
        if(q.size()>m) q.pop();
    }

    int calculateMKAverage(){

        if(q.size()<m) return -1;

        vector<int> v;
        queue<int> temp=q;

        while(!temp.empty()){
            v.push_back(temp.front());
            temp.pop();
        }

        sort(v.begin(),v.end());

        int sum=0;

        for(int i=k;i<m-k;i++)
            sum+=v[i];

        return sum/(m-2*k);
    }
};

