int charge[10000], run[10000], dq[10000];

int main() {
    char input[20000] = "";
    char line[5000];

    while (fgets(line, sizeof(line), stdin)) {
        strcat(input, line);
    }

    char temp[5000];

    // Parse charge
    char *a = strstr(input, "charge=[");
    if (a == NULL) return 0;

    a += 8;
    char *b = strchr(a, ']');

    int len = b - a;
    strncpy(temp, a, len);
    temp[len] = '\0';

    int n = 0;
    char *t = strtok(temp, ",");

    while (t != NULL) {
        charge[n++] = atoi(t);
        t = strtok(NULL, ",");
    }

    // Parse run
    char *c = strstr(input, "run=[");
    if (c == NULL) return 0;

    c += 5;
    char *d = strchr(c, ']');

    len = d - c;
    strncpy(temp, c, len);
    temp[len] = '\0';

    int runSize = 0;
    t = strtok(temp, ",");

    while (t != NULL) {
        run[runSize++] = atoi(t);
        t = strtok(NULL, ",");
    }

    // Parse budget
    char *bp = strstr(input, "budget=");
    if (bp == NULL) return 0;

    long long budget = atoll(bp + 7);

    // Monotonic deque + sliding window
    int front = 0;
    int rear = -1;
    int left = 0;
    int ans = 0;

    long long runningSum = 0;

    for (int right = 0; right < n; right++) {

        // Maintain decreasing chargeTimes deque
        while (front <= rear &&
               charge[dq[rear]] <= charge[right]) {
            rear--;
        }

        dq[++rear] = right;

        runningSum += run[right];

        // Shrink while over budget
        while (front <= rear) {

            long long windowSize = right - left + 1;

            long long cost =
                (long long)charge[dq[front]] +
                windowSize * runningSum;

            if (cost <= budget) {
                break;
            }

            if (dq[front] == left) {
                front++;
            }

            runningSum -= run[left];
            left++;
        }

        int windowSize = right - left + 1;

        if (windowSize > ans) {
            ans = windowSize;
        }
    }

    printf("%d", ans);

    return 0;
}

