using namespace std;

vector<int> parseArray(const string &s, const string &key) {
    vector<int> res;
    size_t pos = s.find(key);
    if (pos == string::npos) return res;
    size_t start = s.find('[', pos);
    size_t end = s.find(']', start);
    if (start == string::npos || end == string::npos) return res;

    string content = s.substr(start + 1, end - start - 1);
    stringstream ss(content);
    string token;
    while (getline(ss, token, ',')) {
        if (!token.empty()) {
            res.push_back(stoi(token));
        }
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string input, line;
    while (getline(cin, line)) {
        input += line + " ";
    }

    vector<int> charge = parseArray(input, "charge");
    vector<int> run = parseArray(input, "run");

    long long budget = 0;
    size_t bpos = input.find("budget=");
    if (bpos != string::npos) {
        budget = stoll(input.substr(bpos + 7));
    }

    deque<int> dq;
    int left = 0;
    int ans = 0;
    long long runningSum = 0;
    int n = charge.size();

    for (int right = 0; right < n; right++) {
        while (!dq.empty() && charge[dq.back()] <= charge[right]) {
            dq.pop_back();
        }
        dq.push_back(right);
        runningSum += run[right];

        while (!dq.empty()) {
            long long windowSize = right - left + 1;
            long long cost = (long long)charge[dq.front()] + windowSize * runningSum;

            if (cost <= budget) {
                break;
            }

            if (dq.front() == left) {
                dq.pop_front();
            }
            runningSum -= run[left];
            left++;
        }

        int windowSize = right - left + 1;
        ans = max(ans, windowSize);
    }

    cout << ans;
    return 0;
}

