    char line[2000];

    while (fgets(line, sizeof(line), stdin)) {
        strcat(input, line);
    }

    int rows = 0, cols = 0;
    char *p = strchr(input, '[');
    if (p == NULL) return 0;
    p++;

    while (*p && *p != ']') {
        while (*p && *p != '[' && *p != ']') {
            p++;
        }
        if (*p == '[') {
            p++;
            int col = 0;
            while (*p && *p != ']') {
                while (*p && !isdigit(*p) && *p != ']') p++;
                if (isdigit(*p)) {
                    grid[rows][col++] = strtol(p, &p, 10);
                }
            }
            if (col > 0) {
                cols = col;
                rows++;
            }
            if (*p == ']') p++;
        }
    }

    if (rows == 0 || cols == 0) {
        printf("0");
        return 0;
    }

    int head = 0, tail = 0;
    int fresh = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == 2) {
                qx[tail] = i;
                qy[tail] = j;
                tail++;
            } else if (grid[i][j] == 1) {
                fresh++;
            }
        }
    }

    int mins = 0;
    int dx[] = {-1, 1, 0, 0};
    int dy[] = {0, 0, -1, 1};

    while (head < tail && fresh > 0) {
        int count = tail - head;
        for (int k = 0; k < count; k++) {
            int cx = qx[head];
            int cy = qy[head];
            head++;

            for (int d = 0; d < 4; d++) {
                int nx = cx + dx[d];
                int ny = cy + dy[d];

                if (nx >= 0 && nx < rows && ny >= 0 && ny < cols && grid[nx][ny] == 1) {
                    grid[nx][ny] = 2;
                    fresh--;
                    qx[tail] = nx;
                    qy[tail] = ny;
