import java.util.*;
import java.util.regex.*;

public class Solution {
    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);

        StringBuilder input = new StringBuilder();

        while (sc.hasNextLine()) {
            input.append(sc.nextLine()).append(" ");
        }

        String s = input.toString();

        Matcher numsMatcher = Pattern.compile("nums=\\[([^\\]]*)\\]").matcher(s);

        if (!numsMatcher.find()) {
            return;
        }

        String[] parts = numsMatcher.group(1).split(",");

        int[] nums = new int[parts.length];

        for (int i = 0; i < parts.length; i++) {
            nums[i] = Integer.parseInt(parts[i].trim());
        }

        Matcher kMatcher = Pattern.compile("k=(-?\\d+)").matcher(s);

        if (!kMatcher.find()) {
            return;
        }

        int k = Integer.parseInt(kMatcher.group(1));

        Deque<Integer> dq = new ArrayDeque<>();
        List<Integer> res = new ArrayList<>();

        for (int i = 0; i < nums.length; i++) {

            while (!dq.isEmpty() && dq.peekFirst() < i - k + 1) {
                dq.pollFirst();
            }

            while (!dq.isEmpty() && nums[dq.peekLast()] < nums[i]) {
                dq.pollLast();
            }

            dq.offerLast(i);

            if (i >= k - 1) {
                res.add(nums[dq.peekFirst()]);
            }
        }

        System.out.println(res);
    }
}

